"""Supersede an incorrect baseline-map reference without rewriting frozen candidate bytes."""
import json
from pathlib import Path
import time

from runtime_identity import HERE, ROOT, ORIGINAL_SOURCE, ORIGINAL_SOURCES, canonical_sha, delta, role, sha, write_new


def main():
    first = HERE / 'runtimes/candidate1'
    destination = HERE / 'runtimes/candidate1-metadata-corrected'
    destination.mkdir()
    original_provenance_file = first / 'source-provenance.json'
    original_descriptor_file = first / 'runtime-descriptor.json'
    old = json.loads(original_provenance_file.read_text())
    descriptor = json.loads(original_descriptor_file.read_text())
    benchmark_sources = json.loads(ORIGINAL_SOURCES.read_text())
    if sha(ORIGINAL_SOURCES) != ORIGINAL_SOURCE.rsplit('sha256-', 1)[1]:
        raise ValueError('Corrected baseline source file does not have the exact measured digest')
    old_baseline_file = ROOT / 'result-coordinate-evidence/final-validation/source-hashes.json'
    old_sources = json.loads(old_baseline_file.read_text())
    if {p:h for p,h in old_sources.items() if role(p)=='production'} != {p:h for p,h in benchmark_sources.items() if role(p)=='production'}:
        raise ValueError('The baseline correction unexpectedly changes production source hashes')
    candidate_sources = json.loads(Path(descriptor['sourceManifestFile']).read_text())
    if '15fe7d5011+followup-source-map-sha256-' + canonical_sha(candidate_sources) != descriptor['sourceIdentity']:
        raise ValueError('Candidate1 actual source identity changed')
    for source, key in [('runtime_identity-used-for-candidate1.py','identityHelperSha256'),
                        ('freeze-candidate-runtime-used-for-candidate1.py','freezeHelperSha256')]:
        if sha(HERE / 'helper-history' / source) != old[key]:
            raise ValueError('Executed helper preimage is missing or changed')
    source_delta = delta(benchmark_sources,candidate_sources)
    role_deltas = {kind:{change:[p for p in paths if role(p)==kind] for change,paths in source_delta.items()}
                   for kind in ('production','test','original_benchmark_driver')}
    corrected = dict(old)
    corrected['originalSourceMapFile'] = str(ORIGINAL_SOURCES)
    corrected['originalSourceMapSha256'] = sha(ORIGINAL_SOURCES)
    corrected['sourceRoleDeltaVersusMeasured'] = role_deltas
    corrected['testSourceScope'] = ('The exact measured-source comparison contains the two prior-delivery '
            'GenericRootHost/NodePredicateRoute fixture corrections plus the NativeResultMaterializer '
            'characterization test change. NativeExpressionDomainFailure already matched the measured source. '
            'The benchmark runtime still uses the exact original frozen test-classes entry.')
    corrected['executedFreezeHelperPreservedAt'] = str(HERE / 'helper-history/freeze-candidate-runtime-used-for-candidate1.py')
    corrected['executedIdentityHelperPreservedAt'] = str(HERE / 'helper-history/runtime_identity-used-for-candidate1.py')
    corrected['metadataCorrection'] = {
        'createdEpochNs':time.time_ns(), 'reason':'The original freeze selected an earlier source-hashes.json while labelling it with measured identity34767935. Only NativeExpressionDomainFailureTest differs between that map and the true benchmark-source-hashes.json; every production entry is identical.',
        'supersedesProvenanceFile':str(original_provenance_file), 'supersedesProvenanceSha256':sha(original_provenance_file),
        'incorrectBaselineFile':str(old_baseline_file), 'incorrectBaselineSha256':sha(old_baseline_file),
        'correctBaselineFile':str(ORIGINAL_SOURCES), 'correctBaselineSha256':sha(ORIGINAL_SOURCES),
        'generator':str(Path(__file__).resolve()),'generatorSha256':sha(Path(__file__)),
        'sourceAndRuntimeBytesChanged':False}
    new_provenance_file = destination / 'source-provenance.json'
    write_new(new_provenance_file,corrected)
    corrected_descriptor = dict(descriptor)
    corrected_descriptor['provenanceFile'] = str(new_provenance_file)
    corrected_descriptor['provenanceSha256'] = sha(new_provenance_file)
    corrected_descriptor['originalSourceManifestFile'] = str(ORIGINAL_SOURCES)
    corrected_descriptor['originalSourceManifestSha256'] = sha(ORIGINAL_SOURCES)
    new_descriptor_file = destination / 'runtime-descriptor.json'
    write_new(new_descriptor_file,corrected_descriptor)
    record = {'format':1,'originalFilesOverwritten':False,'runtimeReplacement':False,
              'sourceIdentityUnchanged':descriptor['sourceIdentity'],
              'productionTreeSha256Unchanged':old['candidateProductionTreeSha256'],
              'oldDescriptorFile':str(original_descriptor_file),'oldDescriptorSha256':sha(original_descriptor_file),
              'newDescriptorFile':str(new_descriptor_file),'newDescriptorSha256':sha(new_descriptor_file),
              'oldProvenanceFile':str(original_provenance_file),'oldProvenanceSha256':sha(original_provenance_file),
              'newProvenanceFile':str(new_provenance_file),'newProvenanceSha256':sha(new_provenance_file),
              'baselineSourceMapDifference':delta(old_sources,benchmark_sources),
              'productionSourcesIdenticalBetweenBaselineMaps':True,
              'supersededClarificationFile':str(HERE/'candidate1-test-source-scope-clarification.json'),
              'supersededClarificationReason':'The proposed three-prior-fixture description was based on the earlier incorrect source map. The exact measured map confirms two prior-delivery fixture corrections.',
              'exactMeasuredBaselineDigest':sha(ORIGINAL_SOURCES)}
    write_new(destination/'correction-record.json',record)
    print(json.dumps({'correctedDescriptor':str(new_descriptor_file),'sourceIdentityUnchanged':descriptor['sourceIdentity'],
                      'productionTreeUnchanged':old['candidateProductionTreeSha256']}))


if __name__ == '__main__':
    main()
